ALTER TABLE libraries ADD COLUMN auto_sync_enabled BOOLEAN NOT NULL DEFAULT FALSE, ADD COLUMN auto_sync_mode VARCHAR(16) NOT NULL DEFAULT 'INTERVAL', ADD COLUMN auto_sync_interval_minutes INT NOT NULL DEFAULT 60, ADD COLUMN auto_sync_hour INT NOT NULL DEFAULT 3, ADD COLUMN auto_sync_minute INT NOT NULL DEFAULT 0, ADD COLUMN scan_on_startup BOOLEAN NOT NULL DEFAULT FALSE, ADD COLUMN next_sync_at VARCHAR(40), ADD COLUMN last_auto_sync_at VARCHAR(40), ADD COLUMN last_error TEXT, ADD COLUMN last_error_at VARCHAR(40);
ALTER TABLE scan_jobs ADD COLUMN trigger_source VARCHAR(32) NOT NULL DEFAULT 'MANUAL';
ALTER TABLE library_paths ADD COLUMN last_checked_at VARCHAR(40), ADD COLUMN last_available_at VARCHAR(40), ADD COLUMN last_error TEXT;
ALTER TABLE server_config ADD COLUMN server_timezone VARCHAR(64) NOT NULL DEFAULT 'America/Sao_Paulo';
CREATE TABLE library_stats (library_id VARCHAR(36) PRIMARY KEY, total_size_bytes BIGINT NOT NULL DEFAULT 0, file_count BIGINT NOT NULL DEFAULT 0, media_item_count BIGINT NOT NULL DEFAULT 0, movie_count BIGINT NOT NULL DEFAULT 0, tv_show_count BIGINT NOT NULL DEFAULT 0, season_count BIGINT NOT NULL DEFAULT 0, episode_count BIGINT NOT NULL DEFAULT 0, unmatched_count BIGINT NOT NULL DEFAULT 0, missing_count BIGINT NOT NULL DEFAULT 0, path_count BIGINT NOT NULL DEFAULT 0, updated_at VARCHAR(40) NOT NULL, FOREIGN KEY(library_id) REFERENCES libraries(id) ON DELETE CASCADE) ENGINE=InnoDB;
